def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    boxes = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 3 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((-1, 0), (1, 0), (0, -1), (0, 1)):
                    yy, xx = y + dy, x + dx
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] == 3 and (yy, xx) not in seen:
                        seen.add((yy, xx))
                        stack.append((yy, xx))
            boxes.append((min(y for y, x in cells), max(y for y, x in cells), min(x for y, x in cells), max(x for y, x in cells)))

    active = set()
    projected = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2:
                continue
            containing = [b for b in boxes if b[0] <= r <= b[1] and b[2] <= c <= b[3]]
            if containing:
                active.add((r, c))
                continue
            # A red marker two columns beyond a rectangle's horizontal edge
            # marks the adjacent edge cell; leave the marker one cell farther out.
            horizontal = []
            for r0, r1, c0, c1 in boxes:
                if r0 <= r <= r1:
                    if c == c0 - 2:
                        horizontal.append((r, c0))
                    elif c == c1 + 2:
                        horizontal.append((r, c1))
            if horizontal:
                nearest = min(abs(c - x) for _, x in horizontal)
                if nearest == 2:
                    edge = min(horizontal, key=lambda p: abs(c - p[1]))
                    active.add(edge)
                    projected.append((r, c, r, c + (1 if c > edge[1] else -1)))

    for r, c in active:
        for y in range(max(0, r - 1), min(h, r + 2)):
            for x in range(max(0, c - 1), min(w, c + 2)):
                out[y][x] = 1
    for r, c in active:
        out[r][c] = 2
    for r, c, rr, cc in projected:
        out[r][c] = 0
        if 0 <= cc < w:
            out[rr][cc] = 2
    return out

